# charset.sh — conversion between the partner ERP code page and UTF-8.
# Everything this tool writes (reports, exports, lookups) is UTF-8.

# charset_to_utf8 TEXT [ENCODING]
#   Converts TEXT from ENCODING (default FEED_ENCODING) to UTF-8.
charset_to_utf8() {
  local raw=$1 enc=${2:-$FEED_ENCODING} out
  [ -n "$raw" ] || return 0
  case "$enc" in
    UTF-8|utf-8|UTF8|utf8) printf '%s' "$raw"; return 0 ;;
  esac
  out=$(printf '%s' "$raw" | iconv -f "$enc" -t UTF-8 -c 2>/dev/null) || out=$raw
  printf '%s' "$out"
}

# charset_is_utf8 TEXT — succeeds when TEXT is well-formed UTF-8.
charset_is_utf8() {
  printf '%s' "$1" | iconv -f UTF-8 -t UTF-8 >/dev/null 2>&1
}

# charset_check_file FILE — succeeds when the whole file is well-formed UTF-8.
charset_check_file() {
  iconv -f UTF-8 -t UTF-8 "$1" >/dev/null 2>&1
}

# Removes carriage returns left by the ERP's Windows transfer job.
charset_strip_cr() {
  local s=$1
  printf '%s' "${s//$'\r'/}"
}
# text.sh — trimming and column layout for the text report.
# Hangul and other non-ASCII characters take two terminal columns.

text_rtrim() {
  local s=$1
  printf '%s' "${s%"${s##*[![:space:]]}"}"
}

text_ltrim() {
  local s=$1
  printf '%s' "${s#"${s%%[![:space:]]*}"}"
}

text_trim() { text_ltrim "$(text_rtrim "$1")"; }

# Number of terminal columns TEXT occupies.
text_width() {
  local s=$1 ascii
  ascii=${s//[^[:ascii:]]/}
  printf '%d' $(( ${#ascii} + 2 * (${#s} - ${#ascii}) ))
}

# text_fit TEXT COLS — cut TEXT so that it fits in COLS columns, marking
# the cut with "~".
text_fit() {
  local s=$1 cols=$2 out="" ch w=0 cw i
  if [ "$(text_width "$s")" -le "$cols" ]; then printf '%s' "$s"; return; fi
  for (( i = 0; i < ${#s}; i++ )); do
    ch=${s:i:1}
    if [[ $ch == [[:ascii:]] ]]; then cw=1; else cw=2; fi
    (( w + cw > cols - 1 )) && break
    out+=$ch; w=$(( w + cw ))
  done
  printf '%s~' "$out"
}

# text_pad TEXT COLS — left-aligned, padded with spaces to COLS columns.
text_pad() {
  local s w
  s=$(text_fit "$1" "$2")
  w=$(text_width "$s")
  printf '%s%*s' "$s" $(( $2 - w )) ''
}

# text_lpad TEXT COLS — right-aligned.
text_lpad() {
  local w
  w=$(text_width "$1")
  printf '%*s%s' $(( $2 > w ? $2 - w : 0 )) '' "$1"
}
# settle.conf — defaults for the partner settlement batch.
# Every value can be overridden from the environment (SETTLE_*), which is
# how the scheduler and the tests point the tool at other directories.

FEED_DIR=${SETTLE_FEED_DIR:-$SETTLE_HOME/fixtures}
MASTER_FILE=${SETTLE_MASTER_FILE:-$SETTLE_HOME/fixtures/partners.dat}
WORK_DIR=${SETTLE_WORK_DIR:-/var/tmp/settle}
OUT_DIR=${SETTLE_OUT_DIR:-/var/lib/settle/out}

# The partner ERP still exports in its original code page.
FEED_ENCODING=${SETTLE_FEED_ENCODING:-EUC-KR}
FEED_PREFIX=feed-
FEED_SUFFIX=.dat

# Report presentation
REPORT_TITLE="파트너 일일 정산"
REPORT_NAME_WIDTH=24
REPORT_CURRENCY=KRW

# Export
EXPORT_DELIM=,
EXPORT_HEADER="date,seq,code,partner,amount,memo"

# Partners with status I are kept in the master but left out of reports.
REPORT_SKIP_INACTIVE=1
steps/_env.sh:3:for _lib in common charset text money cache feed partners ledger report export; do
lib/partners.sh:18:    name=$(charset_strip_cr "$name")
lib/partners.sh:19:    status=$(charset_strip_cr "$status")
lib/partners.sh:20:    cache_put partners "$code" "$(charset_to_utf8 "$name")"
steps/20-normalize.sh:2:# Step 20 — decode the fixed-width feed into normalized.tsv (UTF-8).
steps/20-normalize.sh:11:feed_records "$dir/feed.dat" > "$tmp" || { rm -f "$tmp"; die "decode failed"; }
lib/feed.sh:19:    line=$(charset_strip_cr "$line")
lib/feed.sh:35:      "$(charset_to_utf8 "$name")" "$amount" "$(charset_to_utf8 "$memo")"
lib/feed.sh:44:  line=$(charset_strip_cr "$line")
lib/feed.sh:55:    line=$(charset_strip_cr "$line")

